/// Registry entry for `characterization.lumping`.
pub static LUMPING_SPEC: ModelSpec = ModelSpec {
    id: "characterization.lumping",
    kind: "direct",
    algorithm: None,
    checks: LUMPING_CHECKS,
    cases: LUMPING_CASES,
};

static PEDERSEN_PLUS_SPLIT_CHECKS: &[SpecCheck] = &[
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "molar_mass",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a molar mass; the abundance residual divides a sum of them by another and the table test compares it against a tabulated cut",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "density",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a specific gravity; the gravity residual divides by a sum of `z*M/rho`",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "mole_fraction",
            min: Some(0.0),
            min_inclusive: false,
            max: Some(1.0),
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a mole fraction, and one the class takes the logarithm of to seed the abundance slope",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "first_carbon_number",
            min: Some(6.0),
            min_inclusive: true,
            max: Some(80.0),
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "the molar-mass table begins at C6 and the density table ends at C80, which is the one row its anchor reads",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "last_carbon_number",
            min: Some(7.0),
            min_inclusive: true,
            max: Some(200.0),
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "the molar-mass table ends at C200, and the range is half-open so this must exceed `first_carbon_number` by at least one to leave a cut",
        },
    },
];

