/// Registry entry for `characterization.whitson_gamma_split`.
pub static WHITSON_GAMMA_SPLIT_SPEC: ModelSpec = ModelSpec {
    id: "characterization.whitson_gamma_split",
    kind: "direct",
    algorithm: None,
    checks: WHITSON_GAMMA_SPLIT_CHECKS,
    cases: WHITSON_GAMMA_SPLIT_CASES,
};

static ALL_MODELS: &[&ModelSpec] = &[
    &LUMPING_SPEC,
    &PEDERSEN_PLUS_SPLIT_SPEC,
    &TBP_CLOSURE_SPEC,
    &TBP_DENSITY_SPEC,
    &WHITSON_GAMMA_SPLIT_SPEC,
];

/// Every model in this namespace, in id order.
#[must_use]
pub fn models() -> &'static [&'static ModelSpec] {
    ALL_MODELS
}

/// One model by id, or `None`. Used by the contract tests.
#[must_use]
pub fn model(id: &str) -> Option<&'static ModelSpec> {
    ALL_MODELS.iter().copied().find(|m| m.id == id)
}
